/// The declaration of a registry.
#[derive(PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct RegistrySpec {
    pub fields: Vec<RegistryField>,
    /// The field that identifies a row across revisions (e.g. model_id).
    pub key: String,
    pub name: String,
    /// The object type this registry indexes.
    pub object_ty: DataCatalogObjectTy,
    pub relations: Option<Vec<RegistryRelation>>,
    /// The object field that references the source document (an ObjectId).
    pub source_field: String,
    /// How the source bytes parse: `yaml`, `json`, or `text` (the whole body
    /// as one string — a markdown document, a program).
    pub source_format: String,
    /// The object field holding the source's sha256, verified before projection.
    pub source_hash_field: String,
    /// Bumped when the spec changes shape; rows carry it.
    pub version: u32,
}

impl RegistrySpec {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsRegistrySpec<'a>> {
        use crate::types::generated::registry_generated::RegistrySpecBuilder as FbsRegistrySpecBuilder;

        let mut fields_offsets = Vec::with_capacity(self.fields.len());
        for val in self.fields.iter() {
            let offset = val.serialize_to(builder);
            fields_offsets.push(offset);
        }
        let fields_offset = builder.create_vector(&fields_offsets);
        let key_offset = builder.create_string(&self.key);
        let name_offset = builder.create_string(&self.name);
        let relations_offset = self.relations.as_ref().map(|v| {
            let mut relations_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                relations_offsets.push(offset);
            }
            let relations_offset = builder.create_vector(&relations_offsets);
            relations_offset
        });
        let source_field_offset = builder.create_string(&self.source_field);
        let source_format_offset = builder.create_string(&self.source_format);
        let source_hash_field_offset = builder.create_string(&self.source_hash_field);

        let mut bldr = FbsRegistrySpecBuilder::new(builder);
        bldr.add_fields(fields_offset);
        bldr.add_key(key_offset);
        bldr.add_name(name_offset);
        bldr.add_object_ty(FbsDataCatalogObjectTy::from(self.object_ty));
        if let Some(offset) = relations_offset {
            bldr.add_relations(offset);
        }
        bldr.add_source_field(source_field_offset);
        bldr.add_source_format(source_format_offset);
        bldr.add_source_hash_field(source_hash_field_offset);
        bldr.add_version(self.version);
        bldr.finish()
    }
}

