        let source_field = fbs.source_field().to_owned();
        let source_format = fbs.source_format().to_owned();
        let source_hash_field = fbs.source_hash_field().to_owned();
        let version = fbs.version();
        Self {
            fields,
            key,
            name,
            object_ty,
            relations,
            source_field,
            source_format,
            source_hash_field,
            version,
        }
