impl From<FbsRegistryTable<'_>> for RegistryTable {
    fn from(fbs: FbsRegistryTable<'_>) -> Self {
        let name = fbs.name().to_owned();
        let stream = ObjectId::from(fbs.stream());
        Self { name, stream }
    }
}

impl crate::FbsSerde for RegistryTable {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsRegistryTable>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

/// What a query needs to bind: the registry's streams by table name.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct RegistryTables {
    pub spec: String,
    pub tables: Vec<RegistryTable>,
    pub version: u32,
}

impl RegistryTables {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsRegistryTables<'a>> {
        use crate::types::generated::registry_generated::RegistryTablesBuilder as FbsRegistryTablesBuilder;

        let spec_offset = builder.create_string(&self.spec);
        let mut tables_offsets = Vec::with_capacity(self.tables.len());
        for val in self.tables.iter() {
            let offset = val.serialize_to(builder);
            tables_offsets.push(offset);
        }
        let tables_offset = builder.create_vector(&tables_offsets);

        let mut bldr = FbsRegistryTablesBuilder::new(builder);
        bldr.add_spec(spec_offset);
        bldr.add_tables(tables_offset);
        bldr.add_version(self.version);
        bldr.finish()
    }
}

impl From<FbsRegistryTables<'_>> for RegistryTables {
    fn from(fbs: FbsRegistryTables<'_>) -> Self {
        let spec = fbs.spec().to_owned();
        let mut tables = Vec::new();
        for elem in fbs.tables() {
            tables.push(elem.into());
        }

        let version = fbs.version();
        Self {
            spec,
            tables,
            version,
        }
    }
}

impl crate::FbsSerde for RegistryTables {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsRegistryTables>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

