    #[test]
    fn test_project_result() {
        let t0 = ProjectResult::default();
        let buf = t0.to_fbs_bytes();
        let t1 = ProjectResult::from_fbs_bytes(buf.as_slice()).unwrap();
        assert_eq!(t0, t1);
    }

